// Deterministic-but-varied selection: same title always yields the same
// image within a category, so an NBA doesn't reshuffle every render. Uses
// a djb2-style hash of the seed string modulo the pool size.
function hashSeed(str) {
    let h = 5381;
    const s = String(str || '');
    for (let i = 0; i < s.length; i++) h = (h * 33 + s.charCodeAt(i)) & 0x7fffffff;
    return h;
}

// Stopwords stripped before scoring — high-frequency words that would
// spuriously match every entry.
const STOPWORDS = new Set([
    'a','an','the','and','or','of','to','for','in','on','at','with','by','from',
    'is','are','was','were','be','been','being','it','its','this','that','these',
    'those','as','but','if','then','else','so','than','too','very','can','will',
    'just','also','not','no','yes','off','out','up','down','into','over','under',
    'about','some','any','all','more','most','less','least','how','what','why',
    'when','where','who','which','their','your','our','my','me','you','he','she',
    'we','they','him','her','his','hers','them','one','two','three','many','few'
]);

// Manual keyword boosts — pairs of ["input word", "library-description word"]
// that should score higher than a raw string match. Keeps semantic links
// even when the surface words don't overlap.
const SYNONYMS = {
    'loan': ['loan','financ','lending','credit','application','approv','underwrit','apr'],
    'refi': ['refi','refinanc','rate','interest'],
    'auto': ['auto','car','vehicle','sports','keys','driver'],
    'home': ['home','house','mortgage','heloc','equity','renov','kitchen'],
    'student': ['student','graduat','university','college','tuition'],
    'card': ['card','credit','travel','beach','vacation','rebate','shopping'],
    'retire': ['retire','pension','ira','401k','grandpa','grandkid','yacht','luxury','planning','estate'],
    'wealth': ['wealth','hnw','advis','portfolio','estate','trust'],
    'business': ['business','sba','warehouse','manager','owner','entrepreneur'],
    'commercial': ['commercial','treasury','payroll','receivable','logistics'],
    'insurance': ['insurance','coverage','shield','protec','life','term','property','sports-car'],
    'travel': ['travel','beach','vacation','trip','flight','hotel'],
    'family': ['family','couple','kids','multi-generation','portrait'],
    'checking': ['checking','deposit','savings','account','cash','optimization'],
    'cross': ['cross','bundle','offer','attach','opportunity'],
    'application': ['application','apply','uploaded','form','portal','underwrit']
};

// Tokenize + normalize a string into a scoring bag. Splits on whitespace and
// punctuation, lowercases, drops stopwords and very short tokens, and expands
// each token via the SYNONYMS map so "loan" also matches "financing".
function tokenize(str) {
    const s = String(str || '').toLowerCase();
    const raw = s.split(/[^a-z0-9]+/).filter(w => w && w.length > 2 && !STOPWORDS.has(w));
    const bag = new Set();
    for (const w of raw) {
        bag.add(w);
        // partial roots — capture "financ" so "financing"/"finance" both hit
        if (w.length >= 5) bag.add(w.slice(0, 5));
        const syns = SYNONYMS[w];
        if (syns) for (const s2 of syns) bag.add(s2);
    }
    return bag;
}

function scoreEntry(entry, contextBag) {
    if (!contextBag || !contextBag.size) return 0;
    const descBag = tokenize(entry.description);
    let hits = 0;
    for (const t of contextBag) {
        // Substring match so "loan" hits "loanplanning" and "refinanc" hits "refinance"
        for (const d of descBag) {
            if (d === t || d.indexOf(t) !== -1 || t.indexOf(d) !== -1) {
                hits++;
                break;
            }
        }
    }
    return hits;
}

// Returns a deterministically-picked image entry for a category. If the
// category has no matches, falls back to the full library.
export function pickImageForCategory(category, seed) {
    const pool = NBA_IMAGE_LIBRARY.filter(e => e.categories.indexOf(category) !== -1);
    const list = pool.length ? pool : NBA_IMAGE_LIBRARY;
    const idx = hashSeed(seed || category || 'default') % list.length;
    return list[idx];
}

// Semantic pick: keyword-scores each library entry against the NBA's title +
// why-suggestion. Highest-scoring entry within the category wins; ties are
// broken deterministically by hash so the same NBA always renders the same
// image. Falls back to category-only picking if the copy has no signal or
// no entries score > 0.
export function pickImageForContext(category, ctx) {
    const pool = NBA_IMAGE_LIBRARY.filter(e => e.categories.indexOf(category) !== -1);
    const list = pool.length ? pool : NBA_IMAGE_LIBRARY;
    if (!list.length) return null;

    const contextText = [ctx && ctx.title, ctx && ctx.why, ctx && ctx.brand]
        .filter(Boolean).join(' ');
    const bag = tokenize(contextText);
    if (!bag.size) {
        // No copy to match against — deterministic fallback keyed by title.
        return pickImageForCategory(category, ctx && ctx.title);
    }

    // Score every entry; keep only those with a positive score.
    const scored = list.map(e => ({ entry: e, score: scoreEntry(e, bag) }))
                       .filter(s => s.score > 0);
    if (!scored.length) {
        return pickImageForCategory(category, ctx && ctx.title);
    }

    // Sort by score desc, then by deterministic hash of the URL so ties
    // resolve stably (not alphabetically — that would over-pick early entries).
    scored.sort((a, b) => {
        if (b.score !== a.score) return b.score - a.score;
        return hashSeed(a.entry.url) - hashSeed(b.entry.url);
    });

    // Among the top-scoring entries, pick deterministically by the NBA title
    // so different NBAs at the same top score get different images.
    const topScore = scored[0].score;
    const topGroup = scored.filter(s => s.score === topScore);
    const idx = hashSeed((ctx && ctx.title) || contextText) % topGroup.length;
    return topGroup[idx].entry;
}

// Returns all entries for a category (or all entries if category is falsy).
// Useful for the picker gallery.
export function listImagesForCategory(category) {
    if (!category) return NBA_IMAGE_LIBRARY;
    const pool = NBA_IMAGE_LIBRARY.filter(e => e.categories.indexOf(category) !== -1);
    return pool.length ? pool : NBA_IMAGE_LIBRARY;
}
